import java.util.List;
import java.util.ArrayList;

class Solution {
    public List<Integer> getRow(int rowIndex) {
        List<Integer> row = new ArrayList<>();
        for (int i = 0; i <= rowIndex; i++) {
            row.add(1);
            for (int j = i - 1; j > 0; j--) {
                row.set(j, row.get(j) + row.get(j - 1));
            }
        }
        return row;
    }
}

import java.util.List;
import java.util.ArrayList;

class Solution {
    public List<Integer> getRow(int rowIndex) {
        List<Integer> previous = new ArrayList<>();
        previous.add(1);

        for (int row = 1; row <= rowIndex; row++) {
            List<Integer> current = new ArrayList<>();
            current.add(1);
            for (int col = 1; col < row; col++) {
                current.add(previous.get(col - 1) + previous.get(col));
            }
            current.add(1);
            previous = current;
        }
        return previous;
    }
}

import java.util.List;
import java.util.ArrayList;

class Solution {
    public List<Integer> getRow(int rowIndex) {
        List<Integer> row = new ArrayList<>();
        long value = 1;
        for (int k = 0; k <= rowIndex; k++) {
            row.add((int) value);
            value = value * (rowIndex - k) / (k + 1);
        }
        return row;
    }
}

import java.util.List;
import java.util.ArrayList;

class Solution {
    public List<Integer> getRow(int rowIndex) {
        List<Integer> row = new ArrayList<>();
        for (int i = 0; i <= rowIndex; i++) {
            row.add(0);
        }

        long value = 1;
        for (int k = 0; k <= rowIndex / 2; k++) {
            int coefficient = (int) value;
            row.set(k, coefficient);
            row.set(rowIndex - k, coefficient);
            value = value * (rowIndex - k) / (k + 1);
        }
        return row;
    }
}

import java.util.List;
import java.util.ArrayList;

class Solution {
    public List<Integer> getRow(int rowIndex) {
        List<List<Integer>> triangle = new ArrayList<>();
        for (int row = 0; row <= rowIndex; row++) {
            List<Integer> current = new ArrayList<>();
            for (int col = 0; col <= row; col++) {
                if (col == 0 || col == row) {
                    current.add(1);
                } else {
                    current.add(triangle.get(row - 1).get(col - 1)
                            + triangle.get(row - 1).get(col));
                }
            }
            triangle.add(current);
        }
        return triangle.get(rowIndex);
    }
}
